93	    /** Dedicated audit logger; create side-effects are recorded here so they can be observed independently. */
94	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
95	
96	    /** Dedicated notification logger; the welcome notification enqueued on a successful create is emitted here. */
97	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
98	
99	    /**
100	     * Source of the monotonically increasing {@code seq} stamped on each {@link OwnerCreatedEvent}.
101	     * Incremented once per successful create so the emitted events form a gap-free, strictly increasing
102	     * sequence across all creates handled by this application instance.
103	     */
104	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
105	
106	    /** Request header carrying the client-supplied idempotency key for owner creation. */
107	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
108	
109	    /**
110	     * The fixed version-2 tag mixed into every derived owner identifier (the {@code memberId} region
111	     * code, the {@code householdId} and the {@code identityKey}) so each identifier is rederived and no
112	     * value produced under version 1 is reproduced. It is deliberately kept out of the user-facing
113	     * {@code locality}, {@code timezone} and owner-segment region, which stay the plain region code.
114	     */
115	    static final String VERSION_TAG = "V2";
116	
117	    /**
118	     * Remembers, per already-seen {@code Idempotency-Key}, the id of the owner that create originally
119	     * produced for it. A repeated create carrying a key found here returns that same owner instead of
120	     * creating a duplicate, making owner creation idempotent with respect to the key.
121	     */
122	    private final Map<String, Integer> ownersByIdempotencyKey = new ConcurrentHashMap<>();
