155	        }
156	        if (owners.isEmpty()) {
157	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
158	        }
159	        List<OwnerDto> ownerDtos = owners.stream()
160	            .map(this::toOwnerDtoWithBulkWarning)
161	            .toList();
162	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
