175	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
176	    @Override
177	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
178	        String idempotencyKey = currentIdempotencyKey();
179	        if (idempotencyKey != null) {
180	            Integer existingId = this.ownersByIdempotencyKey.get(idempotencyKey);
181	            if (existingId != null) {
182	                Owner existing = this.clinicService.findOwnerById(existingId);
183	                if (existing != null) {
184	                    return new ResponseEntity<>(toOwnerDtoWithBulkWarning(existing), HttpStatus.OK);
185	                }
186	            }
187	        }
188	        List<String> missingFields = new ArrayList<>();
189	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
190	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
191	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
192	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
193	        String normalizedFlatAddress = normalizeAddress(ownerFieldsDto.getAddress());
194	        boolean hasStructuredAddress = !normalizedAddressLine1.isEmpty();
195	        String normalizedAddress = hasStructuredAddress
196	            ? composeAddress(normalizedAddressLine1, normalizedAddressLine2)
197	            : normalizedFlatAddress;
198	        requireNonBlank(missingFields, "address", normalizedAddress);
199	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
200	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
201	        if (!missingFields.isEmpty()) {
202	            throw new MissingRequiredFieldsException(missingFields);
203	        }
204	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
205	        validateRegistrationDate(ownerFieldsDto.getRegistrationDate());
206	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
207	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
208	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
209	        requireDailyLimitNotReached(registrationDate);
210	        requireCityBelowCapacity(ownerFieldsDto.getCity());
211	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
212	        ownerFieldsDto.setTelephone(normalizedTelephone);
213	        if (ownerFieldsDto.getEmail() != null) {
214	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
215	        }
216	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
217	        HttpHeaders headers = new HttpHeaders();
218	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
219	        owner.setAddress(normalizedAddress);
220	        owner.setAddressLine1(hasStructuredAddress ? normalizedAddressLine1 : null);
221	        owner.setAddressLine2(hasStructuredAddress && !normalizedAddressLine2.isEmpty()
222	            ? normalizedAddressLine2 : null);
223	        owner.setRegistrationDate(registrationDate);
224	        owner.setMemberId(buildMemberId(owner, normalizedTelephone));
225	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
226	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
227	        requireUniqueIdentity(owner);
228	        markPossibleDuplicate(owner, sharesHousehold);
229	        this.clinicService.saveOwner(owner);
230	        if (idempotencyKey != null) {
231	            this.ownersByIdempotencyKey.put(idempotencyKey, owner.getId());
232	        }
233	        OwnerDto ownerDto = toOwnerDtoWithBulkWarning(owner);
234	        AUDIT.info("Owner created id={} memberId={} registrationDate={} membershipLevel={}",
235	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
236	            ownerDto.getMembershipLevel());
237	        String ownerSegment = ownerDto.getOwnerSegment() == null ? null : ownerDto.getOwnerSegment().getValue();
238	        OwnerCreatedEvent event = OwnerCreatedEvent.forCreatedOwner(
239	            OWNER_CREATED_SEQUENCE.incrementAndGet(), owner, ownerDto.getMembershipLevel(), ownerSegment);
240	        AUDIT.info(this.objectMapper.writeValueAsString(event));
241	        NOTIFY.info("Welcome notification enqueued for owner id={} memberId={}",
242	            owner.getId(), owner.getMemberId());
243	        headers.setLocation(UriComponentsBuilder.newInstance()
244	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
245	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
246	    }
