248	    /**
249	     * Returns the {@code Idempotency-Key} header of the request in progress, or {@code null} when the
250	     * header is absent, blank, or there is no active servlet request. The generated {@link OwnersApi}
251	     * signature carries no header parameter, so it is read from the current request context.
252	     */
253	    private static String currentIdempotencyKey() {
254	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
255	            String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
256	            if (key != null && !key.isBlank()) {
257	                return key;
258	            }
259	        }
260	        return null;
261	    }
