356	    /**
357	     * Builds the owner's unified version-2 {@code memberId} as {@code '<REGION><FY><HASH8><CHK>'}:
358	     * {@code REGION} is the version-2 region code, the fixed {@link #VERSION_TAG} prefixed to the plain
359	     * region derived from the owner's postcode (falling back to its city, else {@code 'UNKNOWN'}) via
360	     * {@link OwnerMapper#toRegion} (e.g. {@code 'V2NSW'}); {@code FY} is the 2-digit fiscal year of the
361	     * owner's business-day-adjusted {@code registrationDate}; {@code HASH8} is the first 8 upper-case
362	     * hex characters of the SHA-256 digest of {@code normalizedTelephone + lastName}; and {@code CHK}
363	     * is a single Luhn check digit over the digits of {@code <REGION><FY><HASH8>} (e.g.
364	     * {@code V2NSW261A2B3C4D9}). Because the version tag is prefixed to the region, no version-1 member
365	     * id is ever reproduced.
366	     *
367	     * <p>When the computed id collides with an existing owner's {@code memberId}, it is de-duplicated by
368	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it unique (e.g.
369	     * {@code NSW261A2B3C4D9-2}); the de-duplicated id is returned. Absent a collision the base id is
370	     * returned unchanged.
371	     *
372	     * @param owner the owner being created, with its region-determining postcode/city and
373	     *              registrationDate populated
374	     * @param normalizedTelephone the owner's normalized (E.164) telephone, hashed with the last name
375	     * @return the (de-duplicated) member id for the owner being created
376	     */
377	    private String buildMemberId(Owner owner, String normalizedTelephone) {
378	        String region = VERSION_TAG + ownerMapper.toRegion(owner);
379	        String fy = String.format("%02d", OwnerMapper.fiscalYear(owner.getRegistrationDate()) % 100);
380	        String hash8 = sha256Hex8(normalizedTelephone + owner.getLastName());
381	        String core = region + fy + hash8;
382	        String baseId = core + luhnCheckDigit(core);
383	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
384	            .map(Owner::getMemberId)
385	            .filter(java.util.Objects::nonNull)
386	            .collect(java.util.stream.Collectors.toSet());
387	        if (!existingIds.contains(baseId)) {
388	            return baseId;
389	        }
390	        int n = 2;
391	        while (existingIds.contains(baseId + "-" + n)) {
392	            n++;
393	        }
394	        return baseId + "-" + n;
395	    }
396	
397	    /**
398	     * Computes a single Luhn check digit (0-9) over the decimal digits contained in {@code value};
399	     * non-digit characters are ignored. Used to append the {@code CHK} segment to a member id's
400	     * {@code <REGION><FY><HASH8>} core.
401	     */
402	    private static int luhnCheckDigit(String value) {
403	        int sum = 0;
404	        boolean dbl = true;
405	        for (int i = value.length() - 1; i >= 0; i--) {
406	            char c = value.charAt(i);
407	            if (c < '0' || c > '9') {
408	                continue;
409	            }
410	            int d = c - '0';
411	            if (dbl) {
412	                d *= 2;
413	                if (d > 9) {
414	                    d -= 9;
415	                }
416	            }
417	            sum += d;
418	            dbl = !dbl;
419	        }
420	        return (10 - (sum % 10)) % 10;
421	    }
422	
423	    /**
424	     * Returns the first 8 upper-case hex characters of the SHA-256 digest of {@code value}'s UTF-8
425	     * bytes. Deterministic, so the same input always yields the same 8-character hash.
426	     */
427	    private static String sha256Hex8(String value) {
428	        try {
429	            byte[] digest = MessageDigest.getInstance("SHA-256")
430	                .digest(value.getBytes(StandardCharsets.UTF_8));
431	            StringBuilder sb = new StringBuilder();
432	            for (byte b : digest) {
433	                sb.append(String.format("%02X", b));
434	            }
435	            return sb.substring(0, 8);
436	        }
437	        catch (NoSuchAlgorithmException e) {
438	            throw new IllegalStateException("SHA-256 not available", e);
439	        }
440	    }
