442	    /**
443	     * Counts the existing owners (those already persisted before this create) whose first and last
444	     * names both match the incoming owner's, compared case-insensitively. This snapshot is stored on
445	     * the new owner as its {@code namesakeCount} and echoed back on reads.
446	     *
447	     * @param firstName the incoming owner's first name (already validated non-blank)
448	     * @param lastName the incoming owner's last name (already validated non-blank)
449	     * @return the number of existing namesakes sharing both names case-insensitively
450	     */
451	    private int countNamesakes(String firstName, String lastName) {
452	        return (int) this.clinicService.findAllOwners().stream()
453	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
454	                && lastName.equalsIgnoreCase(existing.getLastName()))
455	            .count();
456	    }
