458	    /**
459	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
460	     * whitespace-only), so the caller can reject the request listing every offending field.
461	     */
462	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
463	        if (value == null || value.isBlank()) {
464	            missingFields.add(fieldName);
465	        }
466	    }
467	
468	    /**
469	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
470	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
471	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
472	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
473	     * {@code "+61412345678"}.
474	     *
475	     * @param telephone the raw telephone value from the request
476	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
477	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
478	     */
479	    private static String normalizeTelephone(String telephone) {
480	        String e164 = toE164(telephone);
481	        if (e164 == null) {
482	            throw new InvalidFieldValueException("telephone",
483	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
484	        }
485	        return e164;
486	    }
487	
488	    /**
489	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
490	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
491	     * owners' stored numbers when detecting duplicates.
492	     */
493	    private static String toE164(String telephone) {
494	        if (telephone == null) {
495	            return null;
496	        }
497	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
498	        String digits;
499	        if (cleaned.startsWith("+")) {
500	            digits = cleaned.substring(1);
501	        } else {
502	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
503	            digits = "61" + national;
504	        }
505	        if (!digits.matches("[0-9]{8,15}")) {
506	            return null;
507	        }
508	        if (!hasValidNationalLength(digits)) {
509	            return null;
510	        }
511	        return "+" + digits;
512	    }
513	
514	    /**
515	     * Checks the national-number length against the country code for the country codes that pin one.
516	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
517	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
518	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
519	     */
520	    private static boolean hasValidNationalLength(String digits) {
521	        if (digits.startsWith("61")) {
522	            return digits.length() - 2 == 9;
523	        }
524	        if (digits.startsWith("1")) {
525	            return digits.length() - 1 == 10;
526	        }
527	        return true;
528	    }
