530	    /**
531	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
532	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
533	     *
534	     * @param email the raw email value from the request (already known to be non-null)
535	     * @return the lower-cased email to be stored and returned
536	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
537	     */
538	    private static String normalizeEmail(String email) {
539	        String trimmed = email.trim();
540	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
541	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
542	        }
543	        String canonical = trimmed.toLowerCase(Locale.ROOT);
544	        String domain = canonical.substring(canonical.indexOf('@') + 1);
545	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
546	            throw new InvalidFieldValueException("email", "Email must not use a disposable-domain address");
547	        }
548	        return canonical;
549	    }
