571	    private static final int MAX_OWNERS_PER_DAY = 100;
572	
573	    /**
574	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
575	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
576	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
577	     * date rolled forward to a business day), so this caps the number that may be created per day.
578	     *
579	     * @param businessDay the adjusted business-day registration date of the owner being created
580	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
581	     */
582	    /**
583	     * The number of owners for a single day beyond which the {@code bulkSignupWarning} flag is
584	     * raised; the warning is true once <em>more than</em> this many owners share a registration date.
585	     */
586	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
