588	    /**
589	     * Maps {@code owner} to its DTO and sets the {@code bulkSignupWarning} flag: {@code true} when
590	     * more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for this
591	     * owner's registration date, otherwise {@code false}.
592	     *
593	     * @param owner the owner to map
594	     * @return the owner DTO with its bulk-signup warning flag populated
595	     */
596	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
597	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
598	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
599	        ownerDto.setCapacityWarning(approachingCityCapacity(owner.getCity()));
600	        int points = OwnerMapper.membershipPointsFor(owner, householdSize(owner.getHouseholdId()));
601	        ownerDto.setMembershipPoints(points);
602	        ownerDto.setMembershipLevel(capMembershipLevel(owner, OwnerMapper.membershipLevelFor(points)));
603	        ownerDto.setRiskFlag(computeRiskFlag(owner));
604	        return ownerDto;
