607	    /**
608	     * Caps the owner's {@code membershipLevel} so it cannot exceed one above the current maximum
609	     * membership level among the other members of its household (existing owners carrying the same
610	     * {@code householdId}, excluding the owner itself and any soft-deleted owner). When the household
611	     * has no other member — including when the owner has no {@code householdId} — no cap applies and
612	     * {@code level} is returned unchanged. Each household member's level is its own base level (points
613	     * mapped to a level for its real household size), so the cap does not depend on other capped
614	     * values.
615	     *
616	     * @param owner the owner whose membership level is being computed
617	     * @param level the owner's uncapped membership level derived from its membership points
618	     * @return the membership level capped at {@code maxHouseholdMemberLevel + 1}, or {@code level}
619	     *         when the owner has no other household member
620	     */
621	    private int capMembershipLevel(Owner owner, int level) {
622	        String householdId = owner.getHouseholdId();
623	        if (householdId == null) {
624	            return level;
625	        }
626	        Integer maxMemberLevel = this.clinicService.findAllOwners().stream()
627	            .filter(existing -> !isDeleted(existing))
628	            .filter(existing -> !java.util.Objects.equals(existing.getId(), owner.getId()))
629	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
630	            .map(this::membershipLevelForOwner)
631	            .max(Integer::compareTo)
632	            .orElse(null);
633	        if (maxMemberLevel == null) {
634	            return level;
635	        }
636	        return Math.min(level, maxMemberLevel + 1);
637	    }
638	
639	    /**
640	     * Computes an existing household member's membership level: its membership points for its real
641	     * household size mapped to the numeric level. Used to establish the household's current maximum
642	     * level when capping a new owner's level.
643	     */
644	    private int membershipLevelForOwner(Owner owner) {
645	        int points = OwnerMapper.membershipPointsFor(owner, householdSize(owner.getHouseholdId()));
646	        return OwnerMapper.membershipLevelFor(points);
647	    }
