649	    /**
650	     * Returns the number of owners sharing the given {@code householdId} (the household's size),
651	     * counting every existing owner that carries the same {@code householdId}. Returns {@code 0} when
652	     * {@code householdId} is {@code null}, since an owner with no postcode has no household key and so
653	     * no household.
654	     *
655	     * @param householdId the owner's computed household identifier, or {@code null} when absent
656	     * @return the number of owners in the household
657	     */
658	    private int householdSize(String householdId) {
659	        if (householdId == null) {
660	            return 0;
661	        }
662	        return (int) this.clinicService.findAllOwners().stream()
663	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
664	            .count();
665	    }
