667	    /**
668	     * Returns whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
669	     * created on {@code registrationDate}, counting existing owners whose {@code registrationDate}
670	     * equals that date. Returns {@code false} when {@code registrationDate} is {@code null}.
671	     */
672	    private boolean exceedsBulkSignupThreshold(LocalDate registrationDate) {
673	        if (registrationDate == null) {
674	            return false;
675	        }
676	        long registeredThatDay = this.clinicService.findAllOwners().stream()
677	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
678	            .count();
679	        return registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
680	    }
