682	    private void requireDailyLimitNotReached(LocalDate businessDay) {
683	        long registeredThatDay = this.clinicService.findAllOwners().stream()
684	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
685	            .count();
686	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
687	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
688	        }
