691	    /**
692	     * Fixed list of public holidays. A registration date landing on one of these dates is rolled
693	     * forward, just like a weekend, until it reaches a non-holiday business day.
694	     */
695	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
696	        LocalDate.of(2026, 1, 1),
697	        LocalDate.of(2026, 1, 26),
698	        LocalDate.of(2026, 4, 25),
699	        LocalDate.of(2026, 12, 25),
700	        LocalDate.of(2026, 12, 28));
701	
702	    /**
703	     * Rolls {@code date} forward to a business day: while it falls on a Saturday, Sunday, or a listed
704	     * public holiday it advances one day at a time until it reaches a non-holiday weekday. Applied to
705	     * the effective registration date (whether supplied in the request or defaulted to the server date)
706	     * so a weekend or holiday registration is recorded on the next business day, and every value derived
707	     * from the registration date uses the adjusted date.
708	     *
709	     * @param date the effective registration date (supplied or defaulted), never {@code null}
710	     * @return the same date, or the next non-holiday business day when {@code date} is a weekend or holiday
711	     */
712	    private static LocalDate toBusinessDay(LocalDate date) {
713	        LocalDate adjusted = date;
714	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
715	            adjusted = adjusted.plusDays(1);
716	        }
717	        return adjusted;
718	    }
719	
720	    /** Whether {@code date} falls on a Saturday or Sunday. */
721	    private static boolean isWeekend(LocalDate date) {
722	        DayOfWeek day = date.getDayOfWeek();
723	        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY;
724	    }
