726	    /** Matches a well-formed postcode: exactly four decimal digits. */
727	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
728	
729	    /**
730	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
731	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
732	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
733	     * present here and accepts any well-formed postcode.
734	     */
735	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
736	        "NSW", new int[] {2000, 2099},
737	        "VIC", new int[] {3000, 3099},
738	        "QLD", new int[] {4000, 4099});
739	
740	    /**
741	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
742	     * optional, so the request contract stays backward-compatible). When present it must be exactly
743	     * four digits and, for a city whose region is known, fall within that region's inclusive range
744	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
745	     * postcode. A malformed or out-of-range value is rejected with a 400.
746	     *
747	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
748	     * @param city the owner's city, used to look up the region whose range constrains the postcode
749	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
750	     */
751	    private void validatePostcode(String postcode, String city) {
752	        if (postcode == null) {
753	            return;
754	        }
755	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
756	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
757	        }
758	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
759	        int[] range = REGION_POSTCODES.get(region);
760	        if (range == null) {
761	            return;
762	        }
763	        int value = Integer.parseInt(postcode);
764	        if (value < range[0] || value > range[1]) {
765	            throw new InvalidFieldValueException("postcode",
766	                "Postcode must be valid for the city's region " + region);
767	        }
768	    }
769	
770	    /**
771	     * Validates an owner's optional {@code registrationDate}. When absent nothing is checked (the
772	     * date defaults to the server date). When present it must not be later than the current server
773	     * date: a registration cannot be recorded in the future, so a future date is rejected with a 400.
774	     *
775	     * @param registrationDate the supplied registration date (may be {@code null} when not supplied)
776	     * @throws InvalidFieldValueException if the supplied date is later than the server date
777	     */
778	    private void validateRegistrationDate(LocalDate registrationDate) {
779	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
780	            throw new InvalidFieldValueException("registrationDate",
781	                "Registration date must not be later than the current date");
782	        }
783	    }
