798	     * capacity check does. Returns {@code false} when {@code city} is {@code null}.
799	     *
800	     * @param city the owner's city, or {@code null}
801	     * @return {@code true} when the city holds 40 to 49 owners, otherwise {@code false}
802	     */
803	    private boolean approachingCityCapacity(String city) {
804	        if (city == null) {
