813	    /**
814	     * Computes the owner's {@code riskFlag}: {@code true} when any of three conditions hold, otherwise
815	     * {@code false}. The owner is risky when it is a possible (soft) duplicate, when its email domain
816	     * is disposable-adjacent (see {@link #isDisposableAdjacentEmail(String)}), or when its city is over
817	     * its soft capacity (see {@link #isCityOverSoftCapacity(String)}). Any one condition is sufficient.
818	     *
819	     * @param owner the owner whose risk flag is computed
820	     * @return {@code true} when the owner is a possible duplicate, has a disposable-adjacent email
821	     *         domain, or lives in a city over its soft capacity; otherwise {@code false}
822	     */
823	    private boolean computeRiskFlag(Owner owner) {
824	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
825	            || isDisposableAdjacentEmail(owner.getEmail())
826	            || isCityOverSoftCapacity(owner.getCity());
827	    }
828	
829	    /**
830	     * Returns whether {@code email}'s domain is disposable-adjacent: its domain equals one of the known
831	     * disposable-mailbox domains ({@link #DISPOSABLE_EMAIL_DOMAINS}) or is a subdomain of one (ends with
832	     * a dot followed by that domain, e.g. {@code inbox.mailinator.com}). Exact-domain matches are
833	     * rejected outright when an owner is created, so in practice this catches the subdomains that slip
834	     * past the create-time blocklist. The comparison is case-insensitive and returns {@code false} for a
835	     * {@code null}, blank, or malformed (no {@code '@'}) address.
836	     *
837	     * @param email the owner's stored email, or {@code null} when absent
838	     * @return {@code true} when the email's domain is on or under a known disposable domain
839	     */
840	    private static boolean isDisposableAdjacentEmail(String email) {
841	        if (email == null || email.isBlank()) {
842	            return false;
843	        }
844	        int at = email.lastIndexOf('@');
845	        if (at < 0 || at == email.length() - 1) {
846	            return false;
847	        }
848	        String domain = email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
849	        for (String disposable : DISPOSABLE_EMAIL_DOMAINS) {
850	            if (domain.equals(disposable) || domain.endsWith("." + disposable)) {
851	                return true;
852	            }
853	        }
854	        return false;
855	    }
