857	    /**
858	     * Returns whether the owner's city is over its soft capacity: {@code true} when the city already
859	     * holds at least {@link #CITY_CAPACITY_WARNING_THRESHOLD} owners (the per-city capacity warning
860	     * threshold, distinct from the hard {@link #MAX_OWNERS_PER_CITY} limit that rejects creation),
861	     * comparing city names case-insensitively as the capacity checks do. Returns {@code false} when
862	     * {@code city} is {@code null}.
863	     *
864	     * @param city the owner's city, or {@code null}
865	     * @return {@code true} when the city holds {@link #CITY_CAPACITY_WARNING_THRESHOLD} or more owners
866	     */
867	    private boolean isCityOverSoftCapacity(String city) {
868	        if (city == null) {
869	            return false;
870	        }
871	        long cityOwners = this.clinicService.findAllOwners().stream()
872	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
873	            .count();
874	        return cityOwners >= CITY_CAPACITY_WARNING_THRESHOLD;
875	    }
