877	    /**
878	     * Rejects the request when the incoming owner's derived {@code identityKey} exactly matches that
879	     * of any existing owner. The key (the SHA-256 hex digest of {@code normalizedTelephone + '|' +
880	     * lowerEmail + '|' + soundex(lastName)}) is the single consolidated duplicate-detection key that
881	     * replaces the former separate telephone, email and household checks. Because the telephone is
882	     * part of the key, two owners with the same last name and postcode but different telephones have
883	     * different keys and are both allowed (they surface as a soft match instead); only an exact
884	     * full-key match is a duplicate. Soft-deleted owners are ignored, and the email-domain blocklist
885	     * has already been applied when the email was normalized. The key is derived identically for the
886	     * incoming and existing owners via {@link OwnerMapper#toIdentityKey}.
887	     *
888	     * @param owner the incoming owner, with its normalized telephone, email and last name
889	     *              already populated
890	     * @throws DuplicateIdentityException if another owner already has this exact identity key
891	     */
892	    private void requireUniqueIdentity(Owner owner) {
893	        String identityKey = ownerMapper.toIdentityKey(owner);
894	        boolean taken = this.clinicService.findAllOwners().stream()
895	            .filter(existing -> !isDeleted(existing))
896	            .map(ownerMapper::toIdentityKey)
897	            .anyMatch(identityKey::equals);
898	        if (taken) {
899	            throw new DuplicateIdentityException(identityKey);
900	        }
901	    }
