903	    /**
904	     * Returns whether an existing owner has been soft-deleted. A soft-deleted owner retains its row
905	     * but is ignored by the create endpoint's duplicate and identity checks, so a normally-blocking
906	     * duplicate is allowed when the only matching owner has been deleted.
907	     */
908	    private static boolean isDeleted(Owner owner) {
909	        return Boolean.TRUE.equals(owner.getDeleted());
910	    }
