912	    /**
913	     * Flags the incoming owner as a possible (soft) duplicate. Called after the hard-duplicate identity
914	     * check has passed, so the owner is known not to be a rejected duplicate. When an existing owner
915	     * has the same {@code soundex(lastName)} and the same {@code postcode} as this owner but a
916	     * <em>different</em> {@code identityKey}, the owner is a possible duplicate: {@code possibleDuplicate}
917	     * is set {@code true} and {@code possibleDuplicateOf} to that existing owner's id (the earliest such
918	     * owner by id when more than one matches). Otherwise both are cleared. A declared household member
919	     * ({@code sharesHousehold} true) is never flagged: it is a deliberate member, not a suspected
920	     * duplicate. An owner with no {@code postcode} never matches, since the soft match is keyed on it.
921	     *
922	     * @param owner the incoming owner, with its telephone, email and postcode populated
923	     * @param sharesHousehold whether the request opted in as a declared household member
924	     */
925	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
926	        owner.setPossibleDuplicate(false);
927	        owner.setPossibleDuplicateOf(null);
928	        if (sharesHousehold) {
929	            return;
930	        }
931	        String postcode = owner.getPostcode();
932	        if (postcode == null || postcode.isBlank()) {
933	            return;
934	        }
935	        String soundex = OwnerIdentity.soundex(owner.getLastName());
936	        String identityKey = ownerMapper.toIdentityKey(owner);
937	        this.clinicService.findAllOwners().stream()
938	            .filter(existing -> !isDeleted(existing))
939	            .filter(existing -> postcode.equals(existing.getPostcode()))
940	            .filter(existing -> soundex.equals(OwnerIdentity.soundex(existing.getLastName())))
941	            .filter(existing -> !identityKey.equals(ownerMapper.toIdentityKey(existing)))
942	            .min(java.util.Comparator.comparing(Owner::getId))
943	            .ifPresent(match -> {
944	                owner.setPossibleDuplicate(true);
945	                owner.setPossibleDuplicateOf(match.getId());
946	            });
947	    }
