949	    /**
950	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
951	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
952	     * comparisons are case-insensitive.
953	     */
954	    private static String normalizeForHousehold(String value) {
955	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
956	    }
957	
958	    /**
959	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
960	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
961	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
962	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
963	     * value normalizes to the empty string, so the required-field check rejects an address that is
964	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
965	     *
966	     * @param address the raw address value from the request (may be {@code null})
967	     * @return the normalized address, or the empty string when blank after normalization
968	     */
969	    private static String normalizeAddress(String address) {
970	        if (address == null) {
971	            return "";
972	        }
973	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
